"""This file contains a number of classes for low level interactions with the Crowbar, Functional
Keypad Interface Test Harness (FkidTh) and Agility Head Simulator (AgilityHeadSim) test tools"""

import logging
from interops.libraries.miscellaneous.registry_functions import match_value_under_registry_subkey
from interops.libraries.desktop.base_ui_page_object import BaseUIPageObject
import interops.libraries.desktop.decorators as deco
from interops.libraries.integrity.linac import Linac
import interops.libraries.integrity.crowbar_fkpidth_objects as crowbar_fkpidth_objects
import interops.libraries.integrity.test_tools.test_tool_utility_functions as test_tool_utility
import squishtest3 as sq


logger = logging.getLogger(__name__)

class FkidTh(BaseUIPageObject):
    application_name = "TestHarness"

    @deco.app_ctx_function()
    def ready(self):
        self.btn_connect = sq.waitForObjectExists(crowbar_fkpidth_objects.connection_Connect_Button)
        self.btn_disconnect = sq.waitForObjectExists(crowbar_fkpidth_objects.connection_Disconnect_Button)
        self.btn_send = sq.waitForObjectExists(crowbar_fkpidth_objects.commands_Send_Button)
        self.chk_reset_timer = sq.waitForObjectExists(crowbar_fkpidth_objects.watchdog_Reset_Timer_CheckBox)
        self.chk_enable_bit = sq.waitForObjectExists(crowbar_fkpidth_objects.commands_Enable_Disable_Bit_CheckBox)
        self.edit_update_period = sq.waitForObjectExists(crowbar_fkpidth_objects.watchdog_Update_Period_Edit)
        self.edit_latch_time = sq.waitForObjectExists(crowbar_fkpidth_objects.commands_Latch_time_Edit)
        self.combo_command = sq.waitForObjectExists(crowbar_fkpidth_objects.commands_Command_ComboBox)

    @deco.app_ctx_function()
    def focus(self):
        sq.setFocusedWindow(crowbar_fkpidth_objects.function_Keypad_Interface_Device_Test_Harness_Window)

    @deco.app_ctx_function()
    def set_command(self, command):
        # setApplicationContext(self.th)
        return test_tool_utility.set_combo_box(self.combo_command, command)

    @deco.app_ctx_function()
    def set_reset_timer(self, checked):
        #    setApplicationContext(self.th)
        return test_tool_utility.check_checkbox(self.chk_reset_timer, checked)

    @deco.app_ctx_function()
    def set_enable_bit(self, checked):
        #    setApplicationContext(self.th)
        return test_tool_utility.check_checkbox(self.chk_enable_bit, checked)

    @deco.app_ctx_function()
    def set_latch_time(self, latch_time):
        # setApplicationContext(self.th)
        self.edit_latch_time.setNativeProperty("Text", latch_time)

    @deco.app_ctx_function()
    def set_update_period(self, update_period):
        # setApplicationContext(self.th)
        self.edit_update_period.setNativeProperty("Text", update_period)

    @deco.app_ctx_function()
    def press_connect(self):
        # setApplicationContext(self.th)
        sq.mouseClick(sq.waitForObject(self.btn_connect))
        # sq.mousePress(sq.waitForObject(self.btn_connect))
        # sq.snooze(1)
        # sq.mouseRelease(sq.waitForObject(self.btn_connect))

    @deco.app_ctx_function()
    def initialise_fkpid(self):
        self.press_connect()
        sq.snooze(1)
        self.set_reset_timer(True)
        sq.snooze(1)
        self.set_command("Authorise")
        sq.snooze(1)
        self.set_enable_bit(True)
        sq.snooze(1)
        sq.mouseClick(sq.waitForObject(self.btn_send))

    @deco.app_ctx_function()
    def start_beam(self):
        try:

            self.set_command("Start MV Radiation")
            sq.snooze(1)
            self.set_enable_bit(True)
            sq.snooze(1)
            sq.mouseClick(sq.waitForObject(self.btn_send))
            sq.snooze(5)
            return True
        except Exception as e:
            logger.info("Error starting beam with FKPid " + str(e))
            return False

    @deco.app_ctx_function()
    def interrupt_beam(self):

        self.set_command("Interrupt MV Radiation")
        sq.snooze(1)
        self.set_enable_bit(True)
        sq.snooze(1)
        sq.mouseClick(sq.waitForObject(self.btn_send))

    @deco.app_ctx_function()
    def asu_gantry(self):
        try:
            linac_info = Linac()
            if linac_info.fkp_asu_with_room_doors_1__open_enabled:
                logger.warning(
                    "ASU with room doors1 open is enabled. Please disable ASU with room doors1 open functionality and rerun. ASU on this Linac was not performed")
                return False
            else:
                self.set_enable_bit(False)
                self.set_command("Enable ASU")
                sq.mouseClick(sq.waitForObject(self.btn_send))
                sq.snooze(1)
                self.set_enable_bit(True)
                sq.snooze(1)
                sq.mouseClick(sq.waitForObject(self.btn_send))
                sq.snooze(1)
                self.set_command("Linac ASU")
                sq.snooze(1)
                self.set_enable_bit(True)
                sq.snooze(1)
                sq.mouseClick(sq.waitForObject(self.btn_send))
                sq.snooze(1)
                return True
        except Exception:
            return False

    def disable_asu(self):
        #         Turn off the ASU

        self.set_command("Linac ASU")
        sq.snooze(1)
        self.set_enable_bit(False)
        sq.snooze(1)
        sq.mouseClick(sq.waitForObject(self.btn_send))

        self.set_command("Enable ASU")
        sq.snooze(1)
        self.set_enable_bit(False)
        sq.mouseClick(sq.waitForObject(self.btn_send))
        sq.snooze(1)

    @staticmethod
    def is_installed():
        subkey = r"SYSTEM\ControlSet001\Control\Class\{36FC9E60-C465-11CF-8056-444553540000}"
        value_name = "ProviderName"
        expectedvalue = "FTDI"
        reg_entry = match_value_under_registry_subkey(subkey, value_name, expectedvalue, hive='HLM')
        installed = reg_entry.strip('\n') == "True"
        return installed